const crypto = require('crypto');

const secret = process.env.LENDLOOP_WEBHOOK_SECRET || process.env.N8N_WEBHOOK_SECRET || 'CHANGE_ME_N8N_WEBHOOK_SECRET';
const item = $input.first().json;
const headers = item.headers || {};
const timestampHeader = headers['x-ll-timestamp'] || headers['x-timestamp'] || headers['X-LL-Timestamp'] || headers['X-Timestamp'];
const signatureHeader = headers['x-ll-signature'] || headers['x-signature'] || headers['X-LL-Signature'] || headers['X-Signature'];
const eventIdHeader = headers['x-ll-event-id'] || headers['x-event-id'] || headers['X-LL-Event-Id'] || headers['X-Event-Id'];

if (!timestampHeader || !signatureHeader) {
  throw new Error('Unauthorized: Missing signature or timestamp headers');
}

const ts = Number(timestampHeader);
const nowSec = Math.floor(Date.now() / 1000);
if (!Number.isFinite(ts) || Math.abs(nowSec - ts) > 300) {
  throw new Error('Unauthorized: Timestamp outside 300s window');
}

const rawBody = typeof item.rawBody === 'string' ? item.rawBody : JSON.stringify(item.body || {});
const method = 'POST';
const path = '/webhook/lendloop-loan-events';
const canonical = `${ts}.${method}.${path}.${rawBody}`;
const computedSig = crypto.createHmac('sha256', secret).update(canonical).digest('hex');

const sigBuffer = Buffer.from(String(signatureHeader).toLowerCase().trim(), 'hex');
const compBuffer = Buffer.from(computedSig, 'hex');

if (sigBuffer.length !== 32 || compBuffer.length !== 32 || !crypto.timingSafeEqual(sigBuffer, compBuffer)) {
  throw new Error('Unauthorized: HMAC signature mismatch');
}

const parsed = typeof item.body === 'object' ? item.body : JSON.parse(rawBody);
return [{
  json: {
    verified: true,
    eventId: eventIdHeader || parsed.eventId,
    type: parsed.type,
    payload: parsed
  }
}];

const p = $input.first().json.payload;
return [{
  json: {
    to: p.recipient.email,
    recipientName: p.recipient.name,
    subject: `[LendLoop] New loan request: ${p.loan.toolName}`,
    bodyText: `Hi ${p.recipient.name},\n\n${p.loan.borrowerName || 'A neighbor'} requested to borrow your ${p.loan.toolName} from ${p.loan.startDate} to ${p.loan.endDate}.\n\nPlease sign in to LendLoop to approve or decline this request.`
  }
}];

const p = $input.first().json.payload;
return [{
  json: {
    to: p.recipient.email,
    recipientName: p.recipient.name,
    subject: `[LendLoop] Request approved: ${p.loan.toolName}`,
    bodyText: `Hi ${p.recipient.name},\n\nGood news! Your request to borrow ${p.loan.toolName} from ${p.loan.startDate} to ${p.loan.endDate} was approved by ${p.loan.ownerName || 'the owner'}.\n\nPlease coordinate pickup and remember to return it by ${p.loan.endDate}.`
  }
}];

const p = $input.first().json.payload;
return [{
  json: {
    to: p.recipient.email,
    recipientName: p.recipient.name,
    subject: `[LendLoop] Request declined: ${p.loan.toolName}`,
    bodyText: `Hi ${p.recipient.name},\n\nYour request to borrow ${p.loan.toolName} for the period ${p.loan.startDate} to ${p.loan.endDate} was declined by the owner.`
  }
}];

const p = $input.first().json.payload;
return [{
  json: {
    to: p.recipient.email,
    recipientName: p.recipient.name,
    subject: `[LendLoop] Request cancelled: ${p.loan.toolName}`,
    bodyText: `Hi ${p.recipient.name},\n\nThe pending request for ${p.loan.toolName} (${p.loan.startDate} to ${p.loan.endDate}) was cancelled by the borrower.`
  }
}];

const p = $input.first().json.payload;
return [{
  json: {
    to: p.recipient.email,
    recipientName: p.recipient.name,
    subject: `[LendLoop] Tool returned: ${p.loan.toolName}`,
    bodyText: `Hi ${p.recipient.name},\n\n${p.loan.toolName} (${p.loan.startDate} to ${p.loan.endDate}) has been marked as returned. Thank you for participating in neighborhood tool sharing!`
  }
}];
